import{_ as t,o,c as s,a0 as a}from"./chunks/framework.B6reNh8h.js";const u=JSON.parse('{"title":"Use the config API","description":"","frontmatter":{},"headers":[],"relativePath":"how-to/use-config-api.md","filePath":"how-to/use-config-api.md"}'),i={name:"how-to/use-config-api.md"};function d(r,e,n,c,l,h){return o(),s("div",null,[...e[0]||(e[0]=[a(`<h1 id="use-the-config-api" tabindex="-1">Use the config API <a class="header-anchor" href="#use-the-config-api" aria-label="Permalink to &quot;Use the config API&quot;">​</a></h1><p><code>tamias-driver-config</code> is the suite&#39;s <strong>common config API</strong> — a first-party pavo driver (Rust, in the workspace) that answers namespaced config queries over the <code>serve</code> wire. It is a convention layered on the <code>query</code> op, not part of the v1 wire contract itself: drivers that need product or host config spawn it and issue queries — they never open config files themselves.</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">printf</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &#39;%s\\n&#39;</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &#39;{&quot;op&quot;:&quot;query&quot;,&quot;query&quot;:&quot;get&quot;,&quot;params&quot;:{&quot;key&quot;:&quot;myco.theme&quot;}}&#39;</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> \\</span></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">  |</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> tamias-driver-config</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> serve</span></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># → {&quot;ok&quot;:true,&quot;result&quot;:{&quot;query&quot;:&quot;get&quot;,&quot;data&quot;:{&quot;key&quot;:&quot;myco.theme&quot;,&quot;value&quot;:&quot;dark&quot;,&quot;found&quot;:true}}}</span></span></code></pre></div><p>Products may later adopt the API natively; until then this driver is the one config surface. It installs with pavo (<code>cargo xtask install</code>) and contributes a <code>config:show</code> view plus a statusbar entry.</p><h2 id="queries" tabindex="-1">Queries <a class="header-anchor" href="#queries" aria-label="Permalink to &quot;Queries&quot;">​</a></h2><table tabindex="0"><thead><tr><th>query</th><th>params</th><th>data</th></tr></thead><tbody><tr><td><code>get</code></td><td><code>key</code> (dotted)</td><td><code>{key, value, found}</code></td></tr><tr><td><code>set</code></td><td><code>key</code>, <code>value</code></td><td><code>{key, value, path, written}</code> or <code>{error}</code></td></tr><tr><td><code>resolve</code></td><td>—</td><td>merged config tree (nested JSON object)</td></tr><tr><td><code>config</code></td><td>—</td><td>merged config flattened to dotted keys</td></tr><tr><td><code>sources</code></td><td>—</td><td>every contributing layer, in precedence order</td></tr></tbody></table><p><code>set</code> writes the <strong>project-level</strong> file: the <code>--config</code>/<code>PAVO_CONFIG</code> path when one was given, else the nearest <code>pavo.toml</code>/<code>pavo.json</code> found walking up from the cwd, else a fresh <code>./pavo.toml</code>. Dotted keys are supported (<code>server.port</code> creates the <code>[server]</code> table); TOML writes preserve comments/formatting (<code>toml_edit</code>), JSON is rewritten pretty-printed. <code>null</code> and nested objects can&#39;t be stored in TOML — use dotted keys for tables.</p><h2 id="resolution-order" tabindex="-1">Resolution order <a class="header-anchor" href="#resolution-order" aria-label="Permalink to &quot;Resolution order&quot;">​</a></h2><p>Layers merge low → high precedence (later wins per-key, nested tables merge recursively):</p><ol><li><strong>defaults</strong> — <code>theme=dark</code>, <code>statusbar=true</code>, <code>refresh_ms=5000</code></li><li><strong>global</strong> — <code>$XDG_CONFIG_HOME/pavo/pavo.{toml,json}</code> or <code>~/.config/pavo/pavo.{toml,json}</code></li><li><strong>project</strong> — <code>pavo.toml</code> and <code>pavo.json</code> in every ancestor of the cwd, filesystem root → cwd (nearest file wins)</li><li><strong>explicit</strong> — <code>--config &lt;path&gt;</code> on argv (manual <code>serve</code> only — pavo&#39;s spawned <code>serve</code> can&#39;t pass argv) or <code>$PAVO_CONFIG</code></li><li><strong>env</strong> — <code>PAVO_CONFIG_*</code> scalar overrides: <code>PAVO_CONFIG_THEME=light</code> → <code>theme</code>; <code>PAVO_CONFIG_MYCO__THEME=x</code> → <code>myco.theme</code> (<code>__</code> = dot, <code>_</code> = literal underscore). Values parse as JSON when possible.</li></ol><p>Formats: <strong>TOML</strong> and <strong>JSON</strong>. <strong>YAML is unsupported</strong> — no yaml dep in the workspace tree; <code>.yaml</code>/<code>.yml</code> files surface as <code>error</code> rows in <code>sources</code> rather than being silently misparsed.</p><h2 id="views" tabindex="-1">Views <a class="header-anchor" href="#views" aria-label="Permalink to &quot;Views&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Deep link</th><th>Route</th><th>Shows</th></tr></thead><tbody><tr><td><code>config:show</code></td><td><code>/config</code></td><td>resolved KV + sources table + resolution doc</td></tr><tr><td><code>config:sources</code></td><td><code>/config/sources</code></td><td>provenance table only</td></tr></tbody></table><p>Contributes a <code>statusbar</code> entry linking to <code>/config</code>.</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">pavo</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> view</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> config:show</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">pavo</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> view</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> config:sources</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">PAVO_CONFIG_THEME</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">light</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> pavo</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> view</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> config:show</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">   # env override wins</span></span></code></pre></div><h2 id="keys-are-namespaced" tabindex="-1">Keys are namespaced <a class="header-anchor" href="#keys-are-namespaced" aria-label="Permalink to &quot;Keys are namespaced&quot;">​</a></h2><p>Callers use dotted paths — <code>myco.theme</code>, <code>kuda.index</code>, <code>pavo.refresh_ms</code> — never file paths or raw TOML. <code>resolve</code> returns the merged tree; <code>sources</code> returns every contributing layer so UIs can show provenance (&quot;this value came from <code>~/.config/pavo/pavo.toml</code>&quot;).</p>`,17)])])}const g=t(i,[["render",d]]);export{u as __pageData,g as default};
